using System.ComponentModel.DataAnnotations;
namespace Veterinaria.Entidades;

public class PropietarioDto { public int IdPropietario { get; set; } public string Nombres { get; set; } = null!; public string Apellidos { get; set; } = null!; public string Dni { get; set; } = null!; public string Telefono { get; set; } = null!; public string Correo { get; set; } = null!; public string Direccion { get; set; } = null!; }
public class PropietarioCrearDto { [Required, StringLength(80)] public string Nombres { get; set; } = null!; [Required, StringLength(80)] public string Apellidos { get; set; } = null!; [Required, StringLength(8), RegularExpression(@"^\d{8}$")] public string Dni { get; set; } = null!; [Required, StringLength(20)] public string Telefono { get; set; } = null!; [Required, StringLength(120), EmailAddress] public string Correo { get; set; } = null!; [Required, StringLength(200)] public string Direccion { get; set; } = null!; }
public class PropietarioActualizarDto : PropietarioCrearDto { [Range(1, int.MaxValue)] public int IdPropietario { get; set; } }
public class MascotaDto { public int IdMascota { get; set; } public string Nombre { get; set; } = null!; public string Especie { get; set; } = null!; public string Raza { get; set; } = null!; public string Sexo { get; set; } = null!; public DateOnly FechaNacimiento { get; set; } public decimal Peso { get; set; } public int IdPropietario { get; set; } public string NombrePropietario { get; set; } = null!; }
public class MascotaCrearDto { [Required, StringLength(80)] public string Nombre { get; set; } = null!; [Required, StringLength(50)] public string Especie { get; set; } = null!; [Required, StringLength(80)] public string Raza { get; set; } = null!; [Required, StringLength(1), RegularExpression("^[MH]$")] public string Sexo { get; set; } = null!; public DateOnly FechaNacimiento { get; set; } [Range(0.01, 500)] public decimal Peso { get; set; } [Range(1, int.MaxValue)] public int IdPropietario { get; set; } }
public class MascotaActualizarDto : MascotaCrearDto { [Range(1, int.MaxValue)] public int IdMascota { get; set; } }
